T = int(input())
for t in range(T):
	(n, k) = input().split(' ')
	n = int(n)
	k = int(k)
	s = input()
	arr = []
	for i in range(n):
		arr.append(s[i])
	prefarr = [0 for i in range(n)]
	c = 0
	a = n - k + 1
	for i in range(n - k + 1):
		if arr[i] == '0' and (c + prefarr[i]) % 2 == 0:
			c += prefarr[i]
			continue
		elif arr[i] == '1' and (c + prefarr[i]) % 2 != 0:
			c += prefarr[i]
			continue
		else:
			prefarr[i] += 1
			if i + k < n:
				prefarr[i + k] -= 1
			c += prefarr[i]
			a -= 1
		if a == 0:
			break
	for i in range(1, len(prefarr)):
		prefarr[i] += prefarr[i - 1]
	ans = ''
	for i in range(len(prefarr)):
		if arr[i] == '0' and prefarr[i] % 2 == 0 or (arr[i] == '1' and prefarr[i] % 2 != 0):
			ans += '0'
		else:
			ans += '1'
	print(ans)
	print('')
